args.CommandLine:
"Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Enum\USB' | ForEach-Object {
  $vidpid = $_.PSChildName
  $subkeys = Get-ChildItem $_.PSPath -ErrorAction SilentlyContinue
  $first = $subkeys | Select-Object -First 1
  if ($first) {
    $p = Get-ItemProperty $first.PSPath -ErrorAction SilentlyContinue
    [PSCustomObject]@{
      VID_PID = $vidpid
      Count = $subkeys.Count
      SampleSerial = $first.PSChildName
      DeviceDesc = $p.DeviceDesc
      FriendlyName = $p.FriendlyName
      Service = $p.Service
      ClassGUID = $p.ClassGUID
      Driver = $p.Driver
      Mfg = $p.Mfg
    }
  }
} | Format-Table -AutoSize -Wrap"

"$targets = @('VID_18D1&PID_0D02','VID_18D1&PID_4E41','VID_18D1&PID_4EE1','VID_18D1&PID_4EE7','VID_1B8E&PID_C003','VID_1B8E&PID_C004','ROOT_HUB30')
foreach ($t in $targets) {
  $path = "HKLM:\SYSTEM\CurrentControlSet\Enum\USB\$t"
  if (Test-Path $path) {
    $sub = Get-ChildItem $path | Select-Object -First 3
    foreach ($s in $sub) {
      $p = Get-ItemProperty $s.PSPath
      [PSCustomObject]@{
        Key = "$t\$($s.PSChildName)"
        DeviceDesc = $p.DeviceDesc
        FriendlyName = $p.FriendlyName
        HardwareID = ($p.HardwareID -join '; ')
        CompatibleIDs = ($p.CompatibleIDs -join '; ')
        Service = $p.Service
        Class = $p.Class
        ClassGUID = $p.ClassGUID
        Driver = $p.Driver
        Mfg = $p.Mfg
        LocationInformation = $p.LocationInformation
        Capabilities = $p.Capabilities
      }
    }
  }
} | Format-List"

"$targets = @('VID_18D1&PID_0D02','VID_18D1&PID_4E41','VID_18D1&PID_4EE1','VID_18D1&PID_4EE7','VID_1B8E&PID_C003','VID_1B8E&PID_C004','ROOT_HUB30','VID_0000&PID_0002','VID_0000&PID_0004')
$out = foreach ($t in $targets) {
  $path = "HKLM:\SYSTEM\CurrentControlSet\Enum\USB\$t"
  if (Test-Path $path) {
    $sub = Get-ChildItem $path | Select-Object -First 2
    foreach ($s in $sub) {
      $p = Get-ItemProperty $s.PSPath
      [PSCustomObject]@{
        Key = "$t\$($s.PSChildName)"
        DeviceDesc = $p.DeviceDesc
        FriendlyName = $p.FriendlyName
        HardwareID = ($p.HardwareID -join '; ')
        CompatibleIDs = ($p.CompatibleIDs -join '; ')
        Service = $p.Service
        Class = $p.Class
        ClassGUID = $p.ClassGUID
        Driver = $p.Driver
        Mfg = $p.Mfg
        LocationInformation = $p.LocationInformation
      }
    }
  }
}
$out | Format-List"

"Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Enum\USB\ROOT_HUB*' | ForEach-Object {
  Get-ChildItem $_.PSPath | ForEach-Object {
    $p = Get-ItemProperty $_.PSPath
    [PSCustomObject]@{
      HubKey = $_.PSChildName
      HardwareID = ($p.HardwareID -join '; ')
      DeviceDesc = $p.DeviceDesc
      Driver = $p.Driver
      ParentIdPrefix = $p.ParentIdPrefix
    }
  }
} | Format-List;
Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Enum\USB' | Where-Object { $_.PSChildName -match '18D1|1B8E|19D2' } | ForEach-Object {
  $vidpid = $_.PSChildName
  $subs = Get-ChildItem $_.PSPath
  $prefixes = $subs | ForEach-Object {
    $p = Get-ItemProperty $_.PSPath
    "$($_.PSChildName) [Loc:$($p.LocationInformation)] [Driver:$($p.Driver)] [Svc:$($p.Service)] [Desc:$($p.DeviceDesc)]"
  } | Select-Object -First 5
  [PSCustomObject]@{
    VID_PID = $vidpid
    TotalInstances = $subs.Count
    Samples = ($prefixes -join " | ")
  }
} | Format-List"

"Get-ChildItem 'C:\Windows\System32\DriverStore\FileRepository' | Where-Object { $_.Name -match 'android_winusb|worldcup' } | ForEach-Object {
  Write-Host "=== $($_.Name) ==="
  Get-ChildItem $_.FullName -Recurse | Select-Object FullName, Length
  $inf = Get-ChildItem $_.FullName -Filter "*.inf" | Select-Object -First 1
  if ($inf) {
    Get-Content $inf.FullName
  }
}"
